function planSprint(stories, capacity) {
  const sorted = [...stories].filter((story) => story.priority !== "wont");
  const selected = [];
  let used = 0;

  for (const story of sorted) {
    if (used + story.points <= capacity) {
      selected.push(story.id);
      used += story.points;
    }
  }

  return {
    selected,
    used,
    leftover: sorted.filter((story) => !selected.includes(story.id)).map((story) => story.id)
  };
}

