  const match = /^as a (.+), i want (.+) so that (.+)$/i.exec(text);
  if (!match) {
    return { valid: false, role: "", goal: "", benefit: "" };
  }

  return {
    valid: true,
    role: match[1].trim(),
    goal: match[2].trim(),
    benefit: match[3].trim()
  };
}

exercise.solution:
function planSprint(stories, capacity) {
  const priorityOrder = { must: 0, should: 1, could: 2 };
  const eligible = stories.filter((story) => story.priority !== "wont");
  const sorted = [...eligible].sort((a, b) => {
    const priorityDifference = priorityOrder[a.priority] - priorityOrder[b.priority];
    if (priorityDifference !== 0) return priorityDifference;
    if (a.points !== b.points) return a.points - b.points;
    return String(a.id).localeCompare(String(b.id));
  });

  const mustPoints = eligible
    .filter((story) => story.priority === "must")
    .reduce((sum, story) => sum + story.points, 0);

  if (mustPoints > capacity) {
    throw new Error("must stories exceed sprint capacity");
  }

  const selected = [];
  const selectedIds = new Set();
  let used = 0;

  for (const story of sorted) {
    if (used + story.points <= capacity) {
      selected.push(story.id);
      selectedIds.add(story.id);
      used += story.points;
    }
  }

  return {
    selected,
    used,
    leftover: sorted.filter((story) => !selectedIds.has(story.id)).map((story) => story.id)
  };
}

function validateStory(text) {
  if (typeof text !== "string") {
    return { valid: false, role: "", goal: "", benefit: "" };
  }

  const match = /^as an?\s+(.+?)\s*,\s*i want\s+(.+?)\s+so that\s+(.+)$/i.exec(text);
  if (!match) {
    return { valid: false, role: "", goal: "", benefit: "" };
  }

  const role = match[1].trim();
  const goal = match[2].trim();
  const benefit = match[3].trim();

  if (!role || !goal || !benefit) {
    return { valid: false, role: "", goal: "", benefit: "" };
  }

  return { valid: true, role, goal, benefit };
}

