const stories = [
  { id: "c1", title: "Dashboard", priority: "could", points: 1 },
  { id: "s1", title: "Tickets", priority: "should", points: 1 },
  { id: "m1", title: "Login", priority: "must", points: 1 }
];
const result = planSprint(stories, 3);
if (JSON.stringify(result.selected) !== JSON.stringify(["m1", "s1", "c1"])) throw new Error("Wrong priority order");
return true;

const stories = [
  { id: "b", title: "B", priority: "should", points: 3 },
  { id: "c", title: "C", priority: "should", points: 1 },
  { id: "a", title: "A", priority: "should", points: 1 }
];
const result = planSprint(stories, 10);
if (JSON.stringify(result.selected) !== JSON.stringify(["a", "c", "b"])) throw new Error("Wrong tie-breaking order");
return true;

const stories = [
  { id: "m1", title: "Large must", priority: "must", points: 3 },
  { id: "s1", title: "Too large", priority: "should", points: 5 },
  { id: "s2", title: "Small enough", priority: "should", points: 2 }
];
const result = planSprint(stories, 5);
if (JSON.stringify(result.selected) !== JSON.stringify(["m1", "s2"])) throw new Error("Did not skip oversized story correctly");
if (result.used !== 5) throw new Error("Wrong used points");
return true;

const stories = [
  { id: "m1", title: "Login", priority: "must", points: 2 },
  { id: "w1", title: "Mobile app", priority: "wont", points: 1 }
];
const result = planSprint(stories, 3);
if (JSON.stringify(result.selected) !== JSON.stringify(["m1"])) throw new Error("Wont story was selected");
if (result.leftover.length !== 0) throw new Error("Wont story appeared in leftover");
return true;

const stories = [
  { id: "m1", title: "Login", priority: "must", points: 3 },
  { id: "m2", title: "Orders", priority: "must", points: 4 }
];
let threw = false;
try {
  planSprint(stories, 6);
} catch (error) {
  threw = error instanceof Error && error.message.toLowerCase().includes("must");
}
if (!threw) throw new Error("Expected must-capacity error");
return true;

const stories = [
  { id: "s2", title: "S2", priority: "should", points: 2 },
  { id: "m1", title: "M1", priority: "must", points: 2 },
  { id: "s1", title: "S1", priority: "should", points: 1 }
];
const result = planSprint(stories, 2);
if (JSON.stringify(result.selected) !== JSON.stringify(["m1"])) throw new Error("Wrong selected stories");
if (JSON.stringify(result.leftover) !== JSON.stringify(["s1", "s2"])) throw new Error("Wrong leftover order");
return true;

const stories = [
  { id: "b", title: "B", priority: "should", points: 2 },
  { id: "a", title: "A", priority: "must", points: 1 }
];
const original = JSON.stringify(stories);
planSprint(stories, 3);
if (JSON.stringify(stories) !== original) throw new Error("Input was mutated");
return true;

const result = validateStory("As a customer, I want to view my orders so that I can track my purchases");
if (!result.valid) throw new Error("Expected valid story");
if (result.role !== "customer") throw new Error("Wrong role");
if (result.goal !== "to view my orders") throw new Error("Wrong goal");
if (result.benefit !== "I can track my purchases") throw new Error("Wrong benefit");
return true;

const result = validateStory("AS AN ADMIN, I WANT to manage tickets SO THAT I can resolve customer issues");
if (!result.valid) throw new Error("Expected valid story");
if (result.role !== "ADMIN") throw new Error("Wrong role");
if (result.goal !== "to manage tickets") throw new Error("Wrong goal");
if (result.benefit !== "I can resolve customer issues") throw new Error("Wrong benefit");
return true;

const invalid = [
  "As a , I want to view orders so that I can track purchases",
  "As a customer, I want  so that I can track purchases",
  "As a customer, I want to view orders so that ",
  "As a customer I want to view orders so that I can track purchases"
];
for (const text of invalid) {
  const result = validateStory(text);
  if (result.valid) throw new Error(`Expected invalid story: ${text}`);
  if (result.role !== "" || result.goal !== "" || result.benefit !== "") throw new Error("Invalid result should contain empty parts");
}
return true;

for (const value of [null, undefined, 42, {}, []]) {
  const result = validateStory(value);
  if (result.valid) throw new Error("Non-string input should be invalid");
  if (result.role !== "" || result.goal !== "" || result.benefit !== "") throw new Error("Invalid result should contain empty parts");
}
return true;
